/usr/bin/bash -lc "python - <<'PY'
from collections import Counter
n=12
w=[[50]*n for _ in range(n)]
for i in range(4):
    a,b,c=3*i,3*i+1,3*i+2
    for u,v,cost in [(a,b,0),(b,c,0),(c,(a+3)%n,5),(a,c,1),(a,(a+4)%n,2)]:
        assert w[u][v]==50
        w[u][v]=w[v][u]=cost
adj=[[v for v in range(n) if v"'!=u and w[u][v]<50] for u in range(n)]
Tedges={tuple(sorted((i,(i+1)%n))) for i in range(n)}
cycles=[]
def dfs(path,mask,cost):
    u=path[-1]
    if len(path)==n:
        if w[u][0]<50 and path[1]<path[-1]:
            edges={tuple(sorted((path[i],path[(i+1)%n]))) for i in range(n)}
            cycles.append((cost+w[u][0],len(Tedges-edges),tuple(path)+(0,)))
        return
    for v in adj[u]:
        if not(mask>>v&1):
            dfs(path+[v],mask|(1<<v),cost+w[u][v])
dfs([0],1,0)
print('"'Edges below 50:',sum(map(len,adj))//2)
print('All undirected Hamiltonian cycles below 50-edge threshold:',len(cycles))
print('Counts by (cost, number of replaced T edges):',sorted(Counter((c,d) for c,d,p in cycles).items()))
for item in sorted(cycles):
    print(item)
print('Minimum cost with at most 6 replacements:',min(c for c,d,p in cycles if d<=6))
print('Minimum distance to strictly improving tour:',min(d for c,d,p in cycles if c<20))
PY"
